logging.pattern.level: "%5p [%X{traceId:-},%X{spanId:-}] order=%X{orderId:-}"

// WRONG: leaks into the next request served by this thread
MDC.put("orderId", order.id().toString());
process(order);

// RIGHT
try (var ignored = MDC.putCloseable("orderId", order.id().toString())) {
    process(order);
}

@Service
public class OrderService {
    private final Counter ordersCreated;
    private final Timer checkoutTime;

    public OrderService(MeterRegistry registry) {
        this.ordersCreated = Counter.builder("orders.created")
            .tag("channel", "web").register(registry);
        this.checkoutTime = Timer.builder("checkout.duration")
            .publishPercentileHistogram()     // can be aggregated across replicas
            .register(registry);
    }

    public void complete(Order o) {
        checkoutTime.record(() -> process(o));
        ordersCreated.increment();
    }
}

